return ['domain'=>'press-permit-core','plural-forms'=>'nplurals=1; plural=0;','language'=>'vi','project-id-version'=>'PublishPress Permissions Free 4.8.2','pot-creation-date'=>'2026-04-22T11:57:22+00:00','po-revision-date'=>'2026-05-26 19:58+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Permissions Free'=>'PublishPress Permissions Free','https://publishpress.com/presspermit'=>'https://publishpress.com/presspermit','PublishPress Permissions allows you to enable or deny access to posts, pages, categories, tags and more.'=>'PublishPress Permissions cho phép bạn bật hoặc từ chối quyền truy cập vào bài viết, trang, danh mục, thẻ và nhiều hơn nữa.','PublishPress'=>'PublishPress','https://publishpress.com/'=>'https://publishpress.com/','Edit Tag for All Post Types'=>'Chỉnh sửa thẻ cho tất cả các loại bài viết','Edit Tag for Posts'=>'Chỉnh sửa thẻ cho bài viết','Advanced Custom Fields'=>'Các trường tùy chỉnh nâng cao','Control front-end access to Field Groups with advanced permission management.'=>'Kiểm soát quyền truy cập phía trước đến các Nhóm Trường với quản lý quyền nâng cao.','Control access to Field Groups'=>'Kiểm soát quyền truy cập đến các nhóm trường','Front-end visibility restrictions'=>'Hạn chế khả năng hiển thị phía trước','Integration with permission groups'=>'Tích hợp với các nhóm quyền','Beaver Builder'=>'Beaver Builder','Compatibility with Edit Permissions in Beaver Builder.'=>'Tương thích với chỉnh sửa quyền trong Beaver Builder.','Beaver editor integration'=>'Tích hợp trình chỉnh sửa Beaver','Widget-level permission controls'=>'Kiểm soát quyền cấp widget','Template access restrictions'=>'Hạn chế quyền truy cập theo mẫu','bbPress Forums'=>'Diễn đàn bbPress','Forum-specific permissions for bbPress with detailed control over forum access and participation.'=>'Quyền riêng cho diễn đàn bbPress với kiểm soát chi tiết về quyền truy cập và tham gia diễn đàn.','Forum-specific permissions'=>'Quyền truy cập cụ thể cho diễn đàn','Topic creation restrictions'=>'Hạn chế tạo chủ đề','Forum access controls'=>'Kiểm soát truy cập diễn đàn','BuddyPress'=>'BuddyPress','Assign post and term permissions to BuddyPress groups for enhanced content control.'=>'Gán quyền bài viết và thuật ngữ cho các nhóm BuddyPress để tăng cường kiểm soát nội dung.','Assign post permissions to BuddyPress groups'=>'Gán quyền bài viết cho các nhóm BuddyPress','Assign term permissions to BuddyPress groups'=>'Gán quyền thuật ngữ cho các nhóm BuddyPress','Group-based content permissions'=>'Quyền nội dung dựa trên nhóm','CMS Tree View'=>'Chế độ xem cây CMS','Compatibility with Edit Permissions in CMS Tree View.'=>'Tương thích với quyền chỉnh sửa trong chế độ xem cây CMS.','Permission-aware tree view'=>'Chế độ xem cây nhận biết quyền','Hierarchical content controls'=>'Kiểm soát nội dung theo cấp bậc','Elementor'=>'Elementor','Compatibility with Edit Permissions in Elementor.'=>'Tương thích với quyền chỉnh sửa trong Elementor.','Elementor editor integration'=>'Tích hợp trình chỉnh sửa Elementor','The Events Calendar'=>'Lịch sự kiện','Apply permission controls to events and event-related content.'=>'Áp dụng kiểm soát quyền cho các sự kiện và nội dung liên quan đến sự kiện.','Event post permissions'=>'Quyền bài viết sự kiện','Event taxonomy controls'=>'Kiểm soát phân loại sự kiện','Nested Pages'=>'Các trang lồng ghép','Compatibility with Edit Permissions in Nested Pages.'=>'Tương thích với quyền chỉnh sửa trong các trang lồng ghép.','Permission-aware nested view'=>'Khả năng xem lồng nhau có nhận thức về quyền','Quick edit integration'=>'Tích hợp chỉnh sửa nhanh','PublishPress Statuses'=>'Trạng thái PublishPress','Compatibility with PublishPress Statuses plugin.'=>'Tương thích với plugin Trạng thái PublishPress.','Custom status permissions'=>'Quyền truy cập trạng thái tùy chỉnh','Workflow-specific access controls'=>'Kiểm soát truy cập theo quy trình làm việc','Status-based editing capabilities'=>'Khả năng chỉnh sửa dựa trên trạng thái','Relevanssi'=>'Relevanssi','Filter search results based on View Permissions for secure content discovery.'=>'Lọc kết quả tìm kiếm dựa trên Quyền Xem để phát hiện nội dung một cách an toàn.','Search result filtering'=>'Lọc kết quả tìm kiếm','Permission-aware indexing'=>'Lập chỉ mục có nhận thức về quyền','Secure content discovery'=>'Khám phá nội dung an toàn','SearchWP'=>'SearchWP','Compatibility with SearchWP term filtering for advanced search capabilities.'=>'Tương thích với lọc thuật ngữ SearchWP để có khả năng tìm kiếm nâng cao.','Permission-aware search results'=>'Kết quả tìm kiếm có nhận thức về quyền','Term-based filtering'=>'Lọc theo thuật ngữ','Advanced search controls'=>'Kiểm soát tìm kiếm nâng cao','WooCommerce'=>'WooCommerce','Apply permission controls to WooCommerce products and product categories.'=>'Áp dụng kiểm soát quyền cho sản phẩm và danh mục sản phẩm WooCommerce.','Product permissions'=>'Quyền sản phẩm','Product category controls'=>'Điều khiển danh mục sản phẩm','WPML'=>'WPML','Multilingual support with permission synchronization across content translations.'=>'Hỗ trợ đa ngôn ngữ với đồng bộ hóa quyền trên các bản dịch nội dung.','Permission synchronization across translations'=>'Đồng bộ hóa quyền truy cập qua các bản dịch','Language-specific content access'=>'Truy cập nội dung theo ngôn ngữ','Multilingual permission management'=>'Quản lý quyền đa ngôn ngữ','Yoast SEO'=>'Yoast SEO','Exclude restricted posts from XML sitemaps to maintain proper SEO indexing.'=>'Loại trừ các bài viết bị hạn chế khỏi XML sitemaps để duy trì chỉ mục SEO đúng cách.','Sitemap filtering for restricted content'=>'Lọc sitemap cho nội dung bị hạn chế','Search engine visibility controls'=>'Điều khiển hiển thị trên công cụ tìm kiếm','Permission-aware XML sitemaps'=>'XML sitemaps nhận biết quyền truy cập','YooTheme'=>'YooTheme','Compatibility with YooTheme builder and term permissions.'=>'Tương thích với trình tạo YooTheme và quyền truy cập theo thuật ngữ.','Builder interface compatibility'=>'Tương thích giao diện trình tạo','Term permission integration'=>'Tích hợp quyền truy cập theo thuật ngữ','Template access controls'=>'Điều khiển truy cập mẫu','Viewing'=>'Xem','Access Circles'=>'Vòng truy cập','Editing Permissions'=>'Chỉnh sửa quyền truy cập','Compatibility Pack'=>'Gói tương thích','Teaser'=>'Teaser','File Access'=>'Truy cập Tệp','Membership'=>'Thành viên','User Posts'=>'Bài viết của Người dùng','Visibility Circles and Editorial Circles block access to content not authored by other group members.'=>'Các Vòng Hiển Thị và Vòng Biên Tập chặn quyền truy cập vào nội dung không được viết bởi các thành viên nhóm khác.','Post-specific and category-specific permissions for creation and editing.'=>'Quyền hạn cụ thể cho bài viết và danh mục cho việc tạo và chỉnh sửa.','Integration with ACF, bbPress, BuddyPress, Relevanssi, WPML and other plugins; enhanced Multisite support.'=>'Tích hợp với ACF, bbPress, BuddyPress, Relevanssi, WPML và các plugin khác; hỗ trợ Multisite nâng cao.','On the site front end, display teaser text for unreadable posts instead of hiding them.'=>'Trên giao diện phía trước của trang, hiển thị văn bản teaser cho các bài viết không đọc được thay vì ẩn chúng.','Restrict direct file requests based on user\'s access to the page a file is attached to.'=>'Hạn chế các yêu cầu tệp trực tiếp dựa trên quyền truy cập của người dùng vào trang mà tệp gắn kèm.','Time-limit access customizations by delaying or expiring Permission Group membership.'=>'Tùy chỉnh thời gian truy cập bằng cách trì hoãn hoặc hết hạn tư cách thành viên Nhóm Quyền.','Auto-create a page for each user of specified roles. Compatible with several Team / Staff plugins.'=>'Tự động tạo một trang cho mỗi người dùng có vai trò đã chỉ định. Tương thích với một số plugin Nhóm / Nhân viên.','Visibility Circles and Editorial Circles block access to content not authored by other group members. Any WP Role, BuddyPress Group or custom Group can be marked as a Circle for specified post types.'=>'Các Vòng Hiển Thị và Vòng Biên Tập chặn quyền truy cập vào nội dung không được viết bởi các thành viên nhóm khác. Bất kỳ Vai Trò WP, Nhóm BuddyPress hoặc Nhóm tùy chỉnh nào cũng có thể được đánh dấu là một Vòng cho các loại bài viết đã chỉ định.','Supports content-specific permissions for editing, term assignment and page parent selection. In combination with other modules, supports workflow statuses, PublishPress and PublishPress Revisions.'=>'Hỗ trợ quyền riêng cho nội dung để chỉnh sửa, gán thuật ngữ và chọn trang cha. Kết hợp với các mô-đun khác, hỗ trợ trạng thái quy trình làm việc, PublishPress và PublishPress Revisions.','Adds compatibility or integration with ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML, various other plugins. Configure any BuddyPress Group as a Permissions Group. For multisite, provides network-wide Permission Groups.'=>'Thêm khả năng tương thích hoặc tích hợp với ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML, và nhiều plugin khác. Cấu hình bất kỳ Nhóm BuddyPress nào làm Nhóm Quyền. Đối với multisite, cung cấp Nhóm Quyền trên toàn mạng.','On the site front end, replace non-readable content with placeholder text. Can be enabled for any post type. Custom filters are provided but no programming is required for basic usage.'=>'Trên giao diện phía trước của trang, thay thế nội dung không đọc được bằng văn bản giữ chỗ. Có thể được bật cho bất kỳ loại bài viết nào. Cung cấp các bộ lọc tùy chỉnh nhưng không yêu cầu lập trình cho việc sử dụng cơ bản.','Filters direct file access, based on user\'s access to post(s) which the file is attached to. No additional configuration required. Creates/modifies .htaccess file in uploads folder (and in main folder for multisite).'=>'Lọc quyền truy cập tệp trực tiếp, dựa trên quyền truy cập của người dùng vào bài viết mà tệp được gắn kèm. Không yêu cầu cấu hình bổ sung. Tạo/sửa đổi tệp .htaccess trong thư mục uploads (và trong thư mục chính cho multisite).','Allows Permission Group membership to be date-limited (delayed and/or scheduled for expiration). Simple date picker UI alongside group membership selection.'=>'Cho phép tư cách thành viên Nhóm Quyền bị giới hạn theo ngày (trì hoãn và/hoặc lên lịch hết hạn). Giao diện chọn ngày đơn giản bên cạnh lựa chọn tư cách thành viên nhóm.','Create or synchronize posts to match users. Designed for Team / Staff plugins, but with broad usage potential.'=>'Tạo hoặc đồng bộ bài viết để phù hợp với người dùng. Thiết kế cho các plugin Nhóm / Nhân viên, nhưng với tiềm năng sử dụng rộng rãi.','If you like %s, please leave us a %s rating. Thank you!'=>'Nếu bạn thích %s, vui lòng để lại cho chúng tôi một đánh giá %s. Cảm ơn bạn!','About PublishPress Permissions'=>'Về PublishPress Permissions','About'=>'Giới thiệu','Permissions Documentation'=>'Tài liệu về quyền truy cập','Documentation'=>'Tài liệu','Contact the PublishPress team'=>'Liên hệ với đội ngũ PublishPress','Contact'=>'Liên hệ','Permission Group'=>'Nhóm quyền truy cập','Specific Permissions: restrictions (\'Blocked\') take priority over additions (\'Enabled\')'=>'Quyền Cụ Thể: các hạn chế (\'Bị chặn\') được ưu tiên hơn các bổ sung (\'Đã kích hoạt\')','Specific Permissions: no restrictions (\'Blocked\') can be applied to custom-defined groups'=>'Quyền riêng biệt: không có hạn chế (\'Bị chặn\') có thể được áp dụng cho các nhóm được định nghĩa tùy chỉnh','Extra Roles assignment available for {All} and {Anonymous} metagroups'=>'Gán vai trò bổ sung có sẵn cho các mét nhóm {All} và {Anonymous}','Allow the {All} and {Anonymous} metagroups to be granted specific reading permissions for private content'=>'Cho phép {All} và {Anonymous} metagroups được cấp quyền đọc cụ thể cho nội dung riêng tư','Users who have specific editing permissions for a post or attachment can also delete it'=>'Người dùng có quyền chỉnh sửa cụ thể cho một bài viết hoặc tệp đính kèm cũng có thể xóa nó','Users who have custom editing permissions for an attachment can also delete it'=>'Người dùng có quyền chỉnh sửa tùy chỉnh cho một tệp đính kèm cũng có thể xóa nó','Disable front end filtering if logged user is a content administrator (normally filter to force inclusion of readable private posts in get_pages() listing, post counts, etc.'=>'Vô hiệu hóa lọc phía trước nếu người dùng đã đăng nhập là quản trị viên nội dung (thông thường lọc để buộc bao gồm các bài viết riêng tư có thể đọc được trong danh sách get_pages(), số lượng bài viết, v.v.)','Disable front end filtering for all users (subject to limitation by PP_UNFILTERED_FRONT_TYPES)'=>'Vô hiệu hóa lọc phía trước cho tất cả người dùng (phụ thuộc vào giới hạn bởi PP_UNFILTERED_FRONT_TYPES)','Comma-separated list of post types to limit the effect of PP_UNFILTERED_FRONT and apply_filters( \'presspermit_skip_cap_filtering\' )'=>'Danh sách các loại bài viết phân cách bằng dấu phẩy để giới hạn hiệu ứng của PP_UNFILTERED_FRONT và apply_filters( \'presspermit_skip_cap_filtering\' )','Specific Permissions: additions (\'Enabled\') are not applied, cannot be assigned'=>'Quyền riêng biệt: các bổ sung (\'Đã bật\') không được áp dụng, không thể được chỉ định','Don\'t assign or apply specific permissions for the \'post\' type'=>'Không gán hoặc áp dụng quyền cụ thể cho loại \'bài viết\'','Don\'t assign or apply specific permissions for the \'page\' type'=>'Không gán hoặc áp dụng quyền cụ thể cho loại \'trang\'','Don\'t assign or apply specific permissions for the \'media\' type'=>'Không gán hoặc áp dụng quyền cụ thể cho loại \'media\'','Don\'t assign or apply specific permissions for the specified custom post type'=>'Không chỉ định hoặc áp dụng quyền riêng biệt cho loại bài viết tùy chỉnh được chỉ định','Include scheduled posts in the posts query if user can edit them'=>'Bao gồm các bài viết đã lên lịch trong truy vấn bài viết nếu người dùng có thể chỉnh sửa chúng','Don\'t filter term post counts in get_terms() call'=>'Không lọc số lượng bài viết theo thuật ngữ trong cuộc gọi get_terms()','Leave unreadable posts on WP Navigation Menus'=>'Để các bài viết không thể đọc được trên Menu Điều Hướng WP','Don\'t apply CSS to hide empty Nav Menus'=>'Không áp dụng CSS để ẩn Menu Điều Hướng trống','For legacy Nav Menus, hide empty nav menu div'=>'Đối với Menu Điều Hướng cũ, ẩn div menu điều hướng trống','Leave terms with no readable posts on WP Navigation Menus'=>'Để lại các thuật ngữ không có bài viết có thể đọc được trên Menu Điều Hướng WP','When Teaser is applied with Redirect enabled, append original url as redirect_to argument'=>'Khi Teaser được áp dụng với Redirect được bật, thêm url gốc như tham số redirect_to','For Teaser compatibility, specify a redirect argument to use instead of redirect_to'=>'Để tương thích với Teaser, chỉ định một tham số chuyển hướng để sử dụng thay vì redirect_to','For Teaser compatibility, specify an additional redirect argument other than redirect_to'=>'Để tương thích với Teaser, chỉ định một tham số chuyển hướng bổ sung khác ngoài redirect_to','For Teaser compatibility, prevent the pp_permissions argument from being appended to redirects'=>'Để tương thích với Teaser, ngăn tham số pp_permissions được thêm vào các chuyển hướng','Filter priority for \'get_pages\' filter (default: 1)'=>'Thứ tự lọc cho bộ lọc \'get_pages\' (mặc định: 1)','Don\'t include readable private pages in the Pages widget or other wp_list_pages() / get_pages() results    '=>'Không bao gồm các trang riêng tư có thể đọc được trong widget Trang hoặc các kết quả wp_list_pages() / get_pages()    ','If some pages have been suppressed from get_pages() results, change child pages\' corresponding post_parent values to a visible ancestor'=>'Nếu một số trang đã bị ẩn khỏi các kết quả get_pages(), thay đổi các giá trị post_parent tương ứng của các trang con thành một tổ tiên có thể nhìn thấy','Never modify the post_parent value in the get_pages() result set, even if some pages have been suppressed'=>'Không bao giờ thay đổi giá trị post_parent trong tập kết quả get_pages(), ngay cả khi một số trang đã bị ẩn','For performance, change the get_pages() database query to return only a subset of fields, excluding post_content'=>'Để cải thiện hiệu suất, thay đổi truy vấn cơ sở dữ liệu get_pages() để chỉ trả về một phần tập hợp các trường, không bao gồm post_content','Don\'t apply content teaser to get_pages() results (leave unreadable posts hidden)'=>'Không áp dụng teaser nội dung cho các kết quả get_pages() (để lại các bài viết không thể đọc được bị ẩn)','If some terms have been suppressed from get_terms() results, change child terms\' corresponding parent values to a visible ancestor'=>'Nếu một số thuật ngữ đã bị ẩn khỏi các kết quả get_terms(), thay đổi các giá trị parent tương ứng của các thuật ngữ con thành một tổ tiên có thể nhìn thấy','Never modify the parent value in the get_terms() result set, even if some terms have been suppressed'=>'Không bao giờ thay đổi giá trị parent trong tập kết quả get_terms(), ngay cả khi một số thuật ngữ đã bị ẩn','Set Author to current user if autoset_post_author / autoset_page_author capability is assigned'=>'Đặt tác giả thành người dùng hiện tại nếu khả năng autoset_post_author / autoset_page_author được gán','Leave Media Library with normal access criteria based on user\'s role capabilities '=>'Rời khỏi Thư viện Media với tiêu chí truy cập bình thường dựa trên khả năng vai trò của người dùng ','Accommodate front end uploading solutions that require page editing capabilities for the async upload request'=>'Cung cấp các giải pháp tải lên phía trước yêu cầu khả năng chỉnh sửa trang cho yêu cầu tải lên không đồng bộ','Treat media attached to unregistered post types as unattached, to avoid improper and confusing filtering'=>'Xử lý media gắn với các loại bài đăng chưa đăng ký như là không gắn, để tránh lọc không đúng và gây nhầm lẫn','Attached Files Private setting available'=>'Cài đặt Riêng tư Tệp đính kèm có sẵn','Comma-separated list of mime types to exclude from File Access filtering'=>'Danh sách các loại mime được phân tách bằng dấu phẩy để loại trừ khỏi lọc Truy cập Tệp','Comma-separated list of mime types to include in File Access filtering (bypassing others)'=>'Danh sách các loại mime phân tách bằng dấu phẩy để bao gồm trong lọc Truy cập Tệp (bỏ qua các loại khác)','When file access is blocked, do not set the WP_Query 404 / 403 property'=>'Khi quyền truy cập tệp bị chặn, không đặt thuộc tính WP_Query 404 / 403','HTTP status code to send when file access is blocked'=>'Mã trạng thái HTTP để gửi khi quyền truy cập tệp bị chặn','On Users listing, Permission groups in custom column are list filter links instead of group edit links'=>'Trong danh sách Người dùng, các nhóm Quyền trong cột tùy chỉnh là các liên kết lọc danh sách thay vì các liên kết chỉnh sửa nhóm','Unlock Permissions > Settings > Core > Admin Back End > \'Hide non-editable posts\''=>'Mở khóa Quyền > Cài đặt > Core > Admin Back End > \'Ẩn các bài viết không thể chỉnh sửa\'','Within the async-upload.php script, filter author\'s retrieval of the attachment they just uploaded'=>'Trong tập lệnh async-upload.php, lọc việc lấy tác giả của tệp đính kèm mà họ vừa tải lên','Don\'t filter comment display or moderation within wp-admin'=>'Không lọc hiển thị hoặc kiểm duyệt bình luận trong wp-admin','Allow Administrators to be added to Permission Groups, even though they are not restricted'=>'Cho phép các Quản trị viên được thêm vào các Nhóm Quyền, ngay cả khi họ không bị hạn chế','If propagating permissions are assigned to a page branch, overwrite any explicitly assigned permissions in sub-pages'=>'Nếu các quyền lan truyền được gán cho một nhánh trang, ghi đè bất kỳ quyền nào được gán rõ ràng trong các trang phụ','Max number of specific permissions to insert in a single database query (default 1000)'=>'Số lượng tối đa các quyền cụ thể để chèn trong một truy vấn cơ sở dữ liệu duy nhất (mặc định 1000)','Don\'t tweak the admin menu indexes to position Permissions menu under Users'=>'Không điều chỉnh chỉ mục menu quản trị để vị trí menu Quyền dưới Người dùng','Don\'t add a Permissions menu. Instead, add menu items to the Users and Settings menus.'=>'Không thêm menu Quyền. Thay vào đó, thêm các mục menu vào menu Người dùng và Cài đặt.','Customize Permissions screen title for Groups'=>'Tùy chỉnh tiêu đề màn hình Quyền cho Nhóm','Customize Permission Groups caption on user profile'=>'Tùy chỉnh chú thích Nhóm Quyền trên hồ sơ người dùng','Only one group is selectable on Add User screen'=>'Chỉ có một nhóm có thể được chọn trên màn hình Thêm Người dùng','Only one group is selectable on Edit User screen'=>'Chỉ có một nhóm có thể được chọn trên màn hình Chỉnh sửa Người dùng','Display a custom hint on Permissions > User Groups'=>'Hiển thị một gợi ý tùy chỉnh trên Quyền > Nhóm người dùng','Max number of non-hierarchical posts / terms to display at one time (per page)'=>'Số lượng tối đa các bài viết / thuật ngữ không phân cấp để hiển thị cùng một lúc (mỗi trang)','Max number of hierarchical posts / terms to display at one time (per page)'=>'Số lượng bài viết / thuật ngữ theo cấu trúc tối đa để hiển thị cùng một lúc (trên mỗi trang)','Disable auto-determination of how many levels of page tree to make visble by default. Instead, use specified value.'=>'Vô hiệu hóa việc tự động xác định số lượng cấp độ của cây trang được hiển thị theo mặc định. Thay vào đó, sử dụng giá trị đã chỉ định.','Target number of visible pages/terms, used for auto-determination of number of visible levels'=>'Số lượng trang/thuật ngữ hiển thị mục tiêu, được sử dụng để tự động xác định số lượng cấp độ hiển thị','Make search function on the post selection metabox look at post content'=>'Làm cho chức năng tìm kiếm trên hộp chọn bài viết xem nội dung bài viết','Make search function on the post selection metabox look at post excerpt'=>'Làm cho chức năng tìm kiếm trên hộp chọn bài viết xem đoạn trích bài viết','Search by last name instead of display name'=>'Tìm kiếm theo họ thay vì tên hiển thị','User field to search by default'=>'Trường người dùng để tìm kiếm theo mặc định','User meta fields selectable for search (comma-separated)'=>'Các trường meta người dùng có thể chọn để tìm kiếm (cách nhau bằng dấu phẩy)','User meta fields which should be treated as numeric (comma-separated)'=>'Các trường meta người dùng sẽ được coi là số (cách nhau bằng dấu phẩy)','User meta fields which should be treated as boolean (comma-separated)'=>'Các trường meta người dùng sẽ được coi là boolean (cách nhau bằng dấu phẩy)','Use display name for search results instead of user_login'=>'Sử dụng tên hiển thị cho kết quả tìm kiếm thay vì user_login','When synchronizing role metagroups to currently defined WP roles, don\'t delete groups for previously defined WP roles.'=>'Khi đồng bộ hóa các nhóm meta vai trò với các vai trò WP hiện tại được định nghĩa, không xóa các nhóm cho các vai trò WP đã định nghĩa trước đó.','Force detection of WP user roles which are appended dynamically but not stored to the WP database.'=>'Buộc phát hiện các vai trò người dùng WP được thêm vào một cách động nhưng không được lưu trữ vào cơ sở dữ liệu WP.','To save memory on front end access, don\'t register any filters related to content editing'=>'Để tiết kiệm bộ nhớ cho truy cập phía trước, không đăng ký bất kỳ bộ lọc nào liên quan đến chỉnh sửa nội dung','Attached media do not have any comments, so don\'t append clauses to comment queries for them'=>'Media gắn không có bất kỳ bình luận nào, vì vậy không thêm các điều khoản vào truy vấn bình luận cho chúng','Reduce overhead of pages query (in get_pages() and wp-admin) by defaulting fields to a set list that does not include post_content '=>'Giảm thiểu chi phí của truy vấn trang (trong get_pages() và wp-admin) bằng cách mặc định hóa các trường thành một danh sách cố định không bao gồm post_content ','Reduce overhead of wp-admin posts query by defaulting fields to a set list that does not include post_content '=>'Giảm chi phí của truy vấn bài viết wp-admin bằng cách mặc định các trường vào một danh sách cố định không bao gồm post_content ','Reduce overhead of wp-admin Media query by defaulting fields to a set list that does not include post_content '=>'Giảm chi phí của truy vấn Media wp-admin bằng cách mặc định các trường vào một danh sách cố định không bao gồm post_content ','Reduce overhead of wp-admin query for specified custom post type by defaulting fields to a set list that does not include post_content '=>'Giảm chi phí của truy vấn wp-admin cho loại bài viết tùy chỉnh được chỉ định bằng cách mặc định các trường vào một danh sách cố định không bao gồm post_content ','Work around database setup warnings (at plugin activation) on some servers'=>'Khắc phục cảnh báo thiết lập cơ sở dữ liệu (khi kích hoạt plugin) trên một số máy chủ','Development use only (suppresses post_status = \'publish\' clause for unfiltered post types with anonymous user)'=>'Chỉ sử dụng cho phát triển (tắt điều khoản post_status = \'publish\' cho các loại bài viết không lọc với người dùng ẩn danh)','Development use only (on front end, do not replace \'post_status = \'publish\'\' clause with filtered equivalent)'=>'Chỉ sử dụng cho phát triển (trên giao diện, không thay thế điều khoản \'post_status = \'publish\'\' bằng phiên bản đã lọc)','Logged In'=>'Đã đăng nhập','Not Logged In'=>'Chưa đăng nhập','Everyone'=>'Mọi người','Change Request Notifications'=>'Thông báo yêu cầu thay đổi','Submitted Revision Editors'=>'Phiên bản Đã gửi','Scheduled Change Notifications'=>'Thông báo thay đổi đã lên lịch','Scheduled Revision Monitors'=>'Giám sát chỉnh sửa đã lên lịch','Authenticated site users, except for Administrators'=>'Người dùng trang đã xác thực, ngoại trừ Quản trị viên','Anonymous users (not logged in)'=>'Người dùng ẩn danh (chưa đăng nhập)','All users (including anonymous)'=>'Tất cả người dùng (bao gồm cả ẩn danh)','All users with the WordPress role of %s'=>'Tất cả người dùng có vai trò WordPress là %s','%1$s %2$s'=>'%1$s %2$s','%1$s won&#39;t work until you upgrade PHP to version %2$s or later. Current version: %3$s'=>'%1$s sẽ không hoạt động cho đến khi bạn nâng cấp PHP lên phiên bản %2$s hoặc mới hơn. Phiên bản hiện tại: %3$s','%1$s won&#39;t work until you upgrade %2$s to version %3$s or later.'=>'%1$s sẽ không hoạt động cho đến khi bạn nâng cấp %2$s lên phiên bản %3$s hoặc mới hơn.','%1$s won&#39;t work until you upgrade WordPress to version %2$s or later.'=>'%1$s sẽ không hoạt động cho đến khi bạn nâng cấp WordPress lên phiên bản %2$s hoặc mới hơn.','This version of %1$s cannot work with your current %2$s version. Please upgrade it to %3$s or later.'=>'Phiên bản %1$s này không thể hoạt động với phiên bản %2$s hiện tại của bạn. Vui lòng nâng cấp lên %3$s hoặc mới hơn.','Duplicate %1$s module activated (%2$s in folder %3$s).'=>'Mô-đun %1$s trùng lặp đã được kích hoạt (%2$s trong thư mục %3$s).','Dismiss'=>'Bỏ qua','Custom Group'=>'Nhóm tùy chỉnh','Custom Groups'=>'Các nhóm tùy chỉnh','Groups'=>'Nhóm','(using default capabilities due to invalid %s definition)'=>'(sử dụng các khả năng mặc định do định nghĩa %s không hợp lệ)','%1$s&nbsp;%2$s&nbsp;%3$s-&nbsp;%4$s%5$s%6$s'=>'%1$s&nbsp;%2$s&nbsp;%3$s-&nbsp;%4$s%5$s%6$s','%1$s&nbsp;%2$s%3$s'=>'%1$s&nbsp;%2$s%3$s','Your license key has expired. For updates to PublishPress Permissions Pro and priority support, %splease renew%s.'=>'Khóa giấy phép của bạn đã hết hạn. Để cập nhật cho PublishPress Permissions Pro và hỗ trợ ưu tiên, %s hãy gia hạn %s.','[WP %s]'=>'[WP %s]','All users with a WordPress %s role'=>'Tất cả người dùng có vai trò WordPress %s','All users who are logged in and have a role on the site'=>'Tất cả người dùng đã đăng nhập và có vai trò trên trang web','Users to notify when revisions are submitted'=>'Người dùng cần thông báo khi có bản sửa đổi được gửi','Users to notify when scheduled revisions are published'=>'Người dùng cần thông báo khi có bản sửa đổi đã lên lịch được công bố','(login timed out)'=>'(phiên đăng nhập đã hết thời gian)','View'=>'Xem','Control assignment of selected terms to %s.'=>'Quản lý việc gán các thuật ngữ đã chọn cho %s.','Control if this %s can be selected as a Parent Page.'=>'Kiểm soát xem %s này có thể được chọn làm Trang Cha hay không.','Control editing of selected %s.'=>'Kiểm soát việc chỉnh sửa %s đã chọn.','Control publishing of selected %s.'=>'Kiểm soát việc xuất bản %s đã chọn.','Control deletion of selected %s.'=>'Kiểm soát việc xóa %s đã chọn.','Control term management for selected %s.'=>'Kiểm soát quản lý thuật ngữ cho %s đã chọn.','Control frontend viewing of selected %s.'=>'Kiểm soát việc xem trên giao diện trước của %s đã chọn.','Control who can create a revision of this %s.'=>'Kiểm soát ai có thể tạo một phiên bản của %s này.','Control who can submit a revision of this %s.'=>'Kiểm soát ai có thể gửi một phiên bản của %s này.','Control which terms can be set as a Parent of other terms.'=>'Kiểm soát các thuật ngữ nào có thể được đặt làm Cha của các thuật ngữ khác.','Allow users to manage selected terms.'=>'Cho phép người dùng quản lý các thuật ngữ đã chọn.','Control management of selected groups.'=>'Quản lý kiểm soát các nhóm đã chọn.','Enable'=>'Kích hoạt','Block'=>'Chặn','Limit to'=>'Giới hạn đến','Expand access to allow specified items regardless of role capabilities or restrictions.'=>'Mở rộng quyền truy cập để cho phép các mục đã chỉ định bất kể khả năng hoặc hạn chế vai trò.','Restrict access by blocking specified items unless an "Enabled" exception is also stored.'=>'Hạn chế quyền truy cập bằng cách chặn các mục đã chỉ định trừ khi một ngoại lệ "Đã bật" cũng được lưu trữ.','Restrict access by limiting role capabilities to apply only for specified items. Users still need capabilities in their main role or extra roles.'=>'Hạn chế quyền truy cập bằng cách giới hạn khả năng vai trò chỉ áp dụng cho các mục đã chỉ định. Người dùng vẫn cần có khả năng trong vai trò chính của họ hoặc vai trò bổ sung.','Using group membership to block access is not recommended. Consider reducing the user\'s role capabilities and using group membership to add access.'=>'Sử dụng tư cách thành viên nhóm để chặn quyền truy cập không được khuyến nghị. Hãy xem xét việc giảm khả năng vai trò của người dùng và sử dụng tư cách thành viên nhóm để thêm quyền truy cập.','Selected:'=>'Đã chọn:','Nav Menus (Legacy)'=>'Menu điều hướng (Cũ)','Legacy'=>'Cũ','%s:'=>'%s:','Selected %s:'=>'Đã chọn %s:','Sub-%s:'=>'Phụ-%s:','All Statuses'=>'Tất cả trạng thái','%s Visibility'=>'%s Hiển thị','No user/group specified.'=>'Không có người dùng/nhóm nào được chỉ định.','You are not permitted to do that.'=>'Bạn không được phép thực hiện điều đó.','Invalid user ID.'=>'ID người dùng không hợp lệ.','Invalid group ID.'=>'ID nhóm không hợp lệ.','Roles updated.'=>'Vai trò đã được cập nhật.','Specific Permissions updated.'=>'Quyền cụ thể đã được cập nhật.','Roles and Permissions copied.'=>'Vai trò và quyền đã được sao chép.','Group updated.'=>'Nhóm đã được cập nhật.','Back to permissions list'=>'Quay lại danh sách quyền','Edit User Permissions'=>'Chỉnh sửa Quyền Người Dùng','Add User Permissions'=>'Thêm Quyền Người Dùng','Edit Permissions'=>'Chỉnh sửa Quyền','Edit Permissions (%s)'=>'Chỉnh sửa Quyền (%s)','%sEdit WordPress Role%s'=>'%sChỉnh sửa Vai Trò WordPress%s','Edit role capabilities directly'=>'Chỉnh sửa khả năng của vai trò trực tiếp','Add New'=>'Thêm Mới','Name:'=>'Tên:','Email:'=>'Email:','Primary Role:'=>'Vai Trò Chính:','User ID:'=>'ID Người Dùng:','Member since:'=>'Thành viên từ:','Description:'=>'Mô tả:','Update Permissions'=>'Cập nhật Quyền','View Full Profile'=>'Xem Hồ Sơ Đầy Đủ','Extra Roles %1$s(from primary role or %2$sgroup membership%3$s)%4$s'=>'Vai trò bổ sung %1$s(từ vai trò chính hoặc %2$sgroup membership%3$s)%4$s','Specific Permissions %1$s(from primary role or %2$sgroup membership%3$s)%4$s'=>'Quyền cụ thể %1$s(từ vai trò chính hoặc %2$sgroup membership%3$s)%4$s','View currently stored user permissions:'=>'Xem quyền người dùng hiện tại đã được lưu trữ:','%1$sUsers who